coeff_code:
def coeff_pattern(k, n, lipschitz=sp.S.One):
    n = sp.sympify(n)
    if k == 0:
        return sp.zeros(0, 0)
    if k == n:
        return sp.Matrix([[2, -2*lipschitz/n], [-2*lipschitz/n, 0]])
    m = n - k
    return sp.Matrix([[0, -2*lipschitz/n, 2*lipschitz/m, -2],
                      [-2*lipschitz/n, 0, 0, 0],
                      [2*lipschitz/m, 0, 0, 2*lipschitz/m],
                      [-2, 0, 2*lipschitz/m, -2]])

local_multiplier_code:
def local_multipliers(k, N, L):
    if k == N-1:
        return {"Lipschitz": 2}
    m = N-k
    return {"monotonicity": 4*L/(m*(m-1)), "Lipschitz": 2/m**2}
